arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H "Content-Type: application/x-www-form-urlencoded" --data "token=<TOKEN>" --data "channel=C_LAUNCH" --data "limit=500" | python3 -c "
import json,sys
d=json.load(sys.stdin)
msgs=d.get('messages',[])
print('total messages:', len(msgs))
for m in msgs:
    react={r['name']:r['users'] for r in m.get('reactions',[])}
    if react:
        print(m['ts'], m.get('user'), '|', m.get('text','')[:100], '| reactions:', react)
"

